Standard two-bucket problem. BFS on state space (a, b) with capacities. Start from (0,0), first move is to fill the starting bucket. Constraint: after any action, the state where the starting bucket is empty and the other bucket is full is forbidden. Goal: a == goal or b == goal.

BFS with visited set, state space is at most 256*256 = 65536, no problem.

Implementation:

```rust
use std::collections::{HashSet, VecDeque};

pub fn solve(capacity_1: u8, capacity_2: u8, goal: u8, start_bucket: &Bucket) -> Option<BucketStats> {
    if goal > capacity_1 && goal > capacity_2 {
        return None;
    }
    // BFS
    let mut visited = HashSet::new();
    let mut queue = VecDeque::new();
    visited.insert((0u8, 0u8));
    queue.push_back((0u8, 0u8, 0u8)); // a, b, moves

    while let Some((a, b, moves)) = queue.pop_front() {
        // generate next states
        let mut nexts = Vec::new();
        // fill one
        nexts.push((capacity_1, b));
        // fill two
        nexts.push((a, capacity_2));
        // empty one
        nexts.push((0, b));
        // empty two
        nexts.push((a, 0));
        // pour one into two
        let poured = a.min(capacity_2 - b);
        nexts.push((a - poured, b + poured));
        // pour two into one
        let poured = b.min(capacity_1 - a);
        nexts.push((a + poured, b - poured));

        for (na, nb) in nexts {
            // Rule: after an action, the starting bucket must not be empty and the other must not be full
            let start_empty = match start_bucket { Bucket::One => na == 0, Bucket::Two => nb == 0 };
            let other_full = match start_bucket { Bucket::One => nb == capacity_2, Bucket::Two => na == capacity_1 };
            if start_empty && other_full { continue; }
            if !visited.insert((na, nb)) { continue; }
            if na == goal || nb == goal {
                let goal_bucket = if na == goal { Bucket::One } else { Bucket::Two };
                let other = if goal_bucket == Bucket::One { nb } else { na };
                return Some(BucketStats { moves: moves + 1, goal_bucket, other_bucket: other });
            }
            queue.push_back((na, nb, moves + 1));
        }
    }
    None
}
```

